svg.script:
const svg = document.documentElement;
const arrows = [...svg.querySelectorAll('path')].map((path) => {
  const box = path.getBBox();
  return {
    path,
    x: box.x + box.width / 2,
    y: box.y + box.height / 2,
    align: parseFloat(getComputedStyle(path).getPropertyValue('--align')) || 0,
    turn: null
  };
});
const cursor = svg.createSVGPoint();
let pendingFrame = 0;
let latestEvent;
let returnTimer = 0;

function pointArrows(event) {
  cursor.x = event.clientX;
  cursor.y = event.clientY;
  const point = cursor.matrixTransform(svg.getScreenCTM().inverse());

  arrows.forEach((arrow) => {
    const pointerAngle = Math.atan2(point.y - arrow.y, point.x - arrow.x) * 180 / Math.PI;
    let turn = arrow.align + pointerAngle + 90;

    if (arrow.turn !== null) {
      while (turn - arrow.turn > 180) turn -= 360;
      while (turn - arrow.turn < -180) turn += 360;
    }

    arrow.turn = turn;
    arrow.path.style.setProperty('--pointer-turn', `${turn}deg`);
  });
}

svg.addEventListener('pointerenter', (event) => {
  clearTimeout(returnTimer);
  svg.classList.remove('returning', 'resume-loop');
  svg.classList.add('tracking');
  pointArrows(event);
});

svg.addEventListener('pointermove', (event) => {
  latestEvent = event;
  if (pendingFrame) return;
  pendingFrame = requestAnimationFrame(() => {
    pointArrows(latestEvent);
    pendingFrame = 0;
  });
});

svg.addEventListener('pointerleave', () => {
  svg.classList.remove('tracking');
  arrows.forEach((arrow) => {
    let north = arrow.align;
    while (north - arrow.turn > 180) north -= 360;
    while (north - arrow.turn < -180) north += 360;
    const direction = north >= arrow.turn ? 1 : -1;

    arrow.path.style.setProperty('--north-turn', `${north}deg`);
    arrow.path.style.setProperty('--return-overshoot', `${north + direction * 10}deg`);
    arrow.path.style.setProperty('--return-rebound', `${north - direction * 6}deg`);
    arrow.path.style.setProperty('--return-settle', `${north + direction * 3}deg`);
  });
  svg.classList.add('returning');

  returnTimer = setTimeout(() => {
    svg.classList.add('resume-loop');
    svg.classList.remove('returning');
    arrows.forEach((arrow) => {
      arrow.turn = null;
      arrow.path.style.removeProperty('--pointer-turn');
      arrow.path.style.removeProperty('--north-turn');
      arrow.path.style.removeProperty('--return-overshoot');
      arrow.path.style.removeProperty('--return-rebound');
      arrow.path.style.removeProperty('--return-settle');
    });
  }, 1200);
});
